Here is the commit message:
cli : fix coverity cli-rl.c

This fixes new coverity issue introduced by commit 5acb74d7da.

Fixes 1395188.

Change-Id: I629e5f214150672e309abb2fc58f55f1f58d8fb7
updates: bz#789278
Signed-off-by: Sunny Kumar <sunkumar@redhat.com>

Here is the root cause:
The bug was caused by a variable naming inconsistency where the code was checking for the nullity of the variable `tokens` instead of the intended variable `token`. This could lead to incorrect behavior in the function `cli_rl_autocomplete_prepare`, as it would not properly validate the presence of the expected token, potentially resulting in null pointer dereferences or incorrect match retrievals.

Here is the patch:

 int
 cli_rl_autocomplete_prepare (struct cli_state *state, const char *text)
 {
         struct cli_cmd_word   *word = NULL;
         struct cli_cmd_word   *next = NULL;
         char                 **tokens = NULL;
         char                 **tokenp = NULL;
         char                  *token = NULL;
         char                 **matches = NULL;

         tokens = cli_rl_tokenize (text);
         if (!tokens)
                 return 0;

         word = &state->tree.root;

         for (tokenp = tokens; (token = *tokenp); tokenp++) {
                 if (!*(tokenp+1)) {
                         /* last word */
                         break;
                 }

                 next = cli_cmd_nextword (word, token);
                 word = next;
                 if (!word)
                         break;
         }

         if (!word)
                 goto out;

-        if (!tokens)
+        if (!token)
                 return 0;
         matches = cli_rl_get_matches (state, word, token);

         state->matches = matches;
         state->matchesp = matches;

 out:
         cli_cmd_tokens_destroy (tokens);
         return 0;
 }



